export default function ProjectCard({
  title,
  description,
  tech,
  image
}: {
  title: string
  description: string
  tech: string[]
  image: string
}) {
  return (
    <div
      style={{
        background: "#111827",
        borderRadius: "12px",
        padding: "20px",
        width: "320px",
        border: "1px solid rgba(255,255,255,0.08)"
      }}
    >
      <img
        src={image}
        style={{
          width: "100%",
          borderRadius: "8px",
          marginBottom: "15px"
        }}
      />

      <h3 style={{ fontSize: "20px", marginBottom: "8px" }}>
        {title}
      </h3>

      <p
        style={{
          fontSize: "15px",
          color: "#9ca3af",
          marginBottom: "12px"
        }}
      >
        {description}
      </p>

      <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
        {tech.map((t) => (
          <span
            key={t}
            style={{
              fontSize: "12px",
              padding: "4px 8px",
              background: "#1f2937",
              borderRadius: "6px"
            }}
          >
            {t}
          </span>
        ))}
      </div>
    </div>
  )
}